function RouteHeading({ title }: { title: string }) {
  const ref = useRef<HTMLHeadingElement>(null);
  const { pathname } = useLocation();

  useEffect(() => {
    ref.current?.focus();
  }, [title]);

  return (
    <h1 ref={ref} className="page-title" onBlur={() => ref.current?.focus()}>
      {title}
    </h1>
  );
}
